import html

def esc(s):return html.escape(str(s),quote=True)
def hero():
    slides=[('/assets/references/ain-diab/04.webp',1440,939,'Livraison au camion-grue · Aïn Diab','/#references'),('/assets/depot/stock-ciment-holcim.webp',1440,810,'Ciment sur palettes · Notre dépôt','/#depot'),('/assets/depot/arrivage-madriers-coffrage.webp',808,1440,'Arrivage de madriers · Bois de coffrage','/?produit=madriers#catalogue'),('/assets/depot/panneaux-muraux-stock-10cm.webp',960,1280,'Panneaux muraux · Stock et pose','/materiaux/panneaux-muraux/')]
    out='<section class="hero hero-photo" data-hero aria-label="Notre activité en images"><div class="hero-slides" aria-hidden="true">'
    for i,(src,w,h,caption,url) in enumerate(slides):out+='<img class="hero-background hero-slide'+(' is-active' if i==0 else '')+'" src="'+src+'" width="'+str(w)+'" height="'+str(h)+'" alt="" '+('fetchpriority="high"' if not i else 'loading="lazy"')+' decoding="async">'
    out+='</div><div class="wrap hero-content"><div class="eyebrow">Gros œuvre · Second œuvre · Logistique</div><h1>Vos matériaux. Votre livraison. Un seul interlocuteur.</h1><p>Matériaux de construction · Préparation des commandes · Livraison chantier</p><div class="actions"><a class="btn" href="#catalogue">Choisir mes matériaux</a><a class="btn outline" href="#depot">Notre travail en images</a></div><a class="hero-credit" data-hero-caption href="'+slides[0][4]+'">© El Boussairi Matériaux · '+slides[0][3]+' ↗</a><div class="hero-controls"><button type="button" class="motion-button" data-hero-prev aria-label="Image précédente du héros">‹</button><div class="hero-dots" role="group" aria-label="Choisir une image">'
    for i,(_,w,h,caption,url) in enumerate(slides):out+='<button type="button" data-hero-dot="'+str(i)+'" data-caption="'+esc(caption)+'" data-url="'+esc(url)+'" aria-label="Image '+str(i+1)+' : '+esc(caption)+'" aria-pressed="'+str(i==0).lower()+'"><span></span></button>'
    return out+'</div><button type="button" class="motion-button" data-hero-next aria-label="Image suivante du héros">›</button><button type="button" class="motion-button motion-pause" data-hero-pause aria-pressed="false">Pause</button></div></div></section>'
def ticker(articles):
    if not articles:return ''
    return '<section class="news-ticker" data-ticker aria-label="Les titres du journal"><div class="wrap ticker-layout"><span class="ticker-label">Le journal</span><div class="ticker-window"><div class="ticker-line"><div class="ticker-set">'+''.join('<a href="/actualites/'+a['slug']+'/"><img src="'+esc(a['cover'])+'" alt="" width="60" height="44" loading="lazy"><span>'+esc(a['title'])+'</span><span aria-hidden="true">↗</span></a>' for a in articles[:8])+'</div></div></div><button type="button" class="motion-button" data-ticker-pause aria-pressed="false" aria-label="Mettre les titres en pause">Pause</button></div></section>'
def news_controls():
    return '<div class="news-controls"><button type="button" class="gallery-arrow" data-news-prev aria-label="Article précédent">‹</button><button type="button" class="gallery-arrow" data-news-next aria-label="Article suivant">›</button><button type="button" class="motion-button" data-news-pause aria-pressed="false">Pause</button></div>'
